STORE = {}
MAX_ENTRIES = 100


def put(key, value):
    if len(STORE) >= MAX_ENTRIES and key not in STORE:
        oldest = next(iter(STORE))
        del STORE[oldest]
    STORE[key] = value


def get(key):
    return STORE.get(key)

import cache


def test_early_entries_survive_eviction():
    for i in range(150):
        cache.put('k%d' % i, i)
    assert cache.get('k149') == 149
    assert len(cache.STORE) <= cache.MAX_ENTRIES
